import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-venue-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==60 and rep['all_bytes_equal'] and rep['matched_files']==103 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('VX_INFO','VX_PRICE','VX_RAW','VX_INV','VX_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='VX_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('VX_PRICE','VX_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['constraint_days']])
 evidence={'build':'1003v1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; FX-adjusted external venue information with current API vintage and surviving venue selection; no accepted strategy'}
 (DOWN/'btc-venue-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-venue-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-venue-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_venue_study.py','test_btc_venue_study.py','verify_btc_venue_study.py','reproduce_btc_venue_study.py','audit_btc_venue_data.py','collect_btc_venue_data.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for n in ('independent-audit.json','data-audit.json','archive-manifest.json','masks.json'):files.append((ROOT/'data/btc-venue-20261003'/n,'input/'+n))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),'All 60 accounts, features, forecasts, audits, masks and source metadata included. Frozen raw Coinbase BTCUSD/USDTUSD and Bitstamp BTCUSD responses and normalized candles remain separate local reproduction inputs (hashes and URLs provided), as do official Binance BTC spot/perp/mark/funding archives and common dependencies. Re-downloading current API data need not recover this exact vintage. No external-venue trades, USDT strategy, live trading or external research code execution.\n')
 html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 거래소 공통 가격정보 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003v1</p><h1>같은 BTC의 다른 가격,<br>새 수익 근거는 아니었습니다.</h1><p class="lead">Coinbase·Bitstamp의 가격괴리를 USD/USDT로 환산하고, 두 장소가 같은 방향일 때만 추가 정보를 사용했습니다. 기본 후보는 최근 손실과 가격 대조보다 큰 예측오차로 기각했습니다.</p><div class="facts"><article><b>60</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>VX_INFO 기본 후보</span></article><article><b>103</b><span>파일 오프라인 바이트 일치</span></article></div><p class="boundary">2022–2025와 2026.01–08은 이미 본 개발 자료입니다. 미사용 OOS·실전 수익이 아닙니다. 외부 BTC 가격과 환산율은 정보로만 쓰며 거래소 간 송금·차익거래나 USDT 매매를 하지 않았습니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT. 수익과 최대낙폭(DD)은 %. TREND는 기존 E_SPOT와 일별·주요회계가 동일합니다.</p>'''+table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')+'''<p>기본은 주 +50.67%·DD13.71%, 최근 −5.16%·DD7.78%입니다. 주수익&gt;52.838713%·DD≤13.561952%, 최근수익&gt;4.628391%라는 기존 기준을 유지했습니다. 주 연변동성13.55%와 2022·2025 연간 손실도 미달입니다. 반대 대조의 최근 +5.42%만 골라 기본 후보를 바꾸지 않았습니다.</p></section><section><h2>괴리와 통화 차이를 구분했습니다</h2><p>USD 가격을 BTCUSDT 가격과 직접 비교하지 않았습니다. USD/USDT 환산율 F를 곱한 BTCUSDT×F와 비교하고, 두 거래소 괴리를 같은 시간으로 맞춰 24시간 평균했습니다. 외부 완료봉에는 추가1시간 가용 대기를 두었습니다. FX는 환산 입력일 뿐 다른 자산 전략이 아닙니다.</p><p>일간 가격·7일 가격·환산율 변화 대조에 공통 괴리를 추가한 양의 계수 제약 회귀입니다. 과거365일의 완성된 다음날 수익만 학습하고 하루 더 분리했습니다. 예측이 비용+표준오차를 넘고 가격 대조보다 같은 방향의 정보를 주며 두 장소도 동의할 때만 기존 가격추세를 바꿉니다. 기본 발동은 주52일·최근7일이었습니다.</p><p>PRICE는 가격·호가통화만, RAW는 USD/USDT를1로 잘못 간주한 진단, INV는 같은 날 반대 방향, TREND는 기존 가격추세입니다. 분산분해의 높은 연결성은 적중률이 아니며 영구적 선도 거래소를 가정하지 않았습니다. 원문 고빈도 모형의 복제도 아닙니다.</p></section><section><h2>먼저 원자료와 가용성을 검사했습니다</h2><p>공식439응답·140,227시간행·436중첩쌍을 독립 Decimal로 대조했습니다. Coinbase BTC13시간·환산율88시간 결측, Bitstamp6시간 무거래를 보존하고 신호에서 제외했습니다. 직전값 채움이나 보간은 없습니다.</p><p>고정18개 일봉 대조 중17개는 시간봉 집계와 가격·거래량이 일치했습니다. 최초 USDT 일봉은 실제 빈응답이고 시간봉도 없어 제외했습니다. 최초 검산기의 존재 가정으로 중단된 로그도 보존했습니다. 현재 공식 API의 과거 응답은 당시 최초 공표 빈티지나 모든 수정 이력의 증명이 아닙니다.</p></section><section><h2>예측오차도 개선되지 않았습니다</h2><p>기본 INFO의 다음1일 수익 MSE는 주0.000745745 / 최근0.000618736, PRICE는 0.000744392 / 0.000614607로 양기간 모두 대조가 낫습니다. 추가24시간 자료지연의 최근 +1.24%를 기본 −5.16% 대신 제시하지 않았습니다.</p><details><summary>모든 예측과 추가24시간 자료지연</summary>'''+table(['기간','추가지연(시간)','모형','공통표본','MSE','방향정확도%','제약활성일'],forecast,'forecast-results')+'</details><details><summary>연도별 수익</summary>'+table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')+'</details><details><summary>롱숏·비용·펀딩·위험</summary>'+table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')+'</details><details><summary>대조군 차이의 불확실성</summary><p>14일 블록2,000회95%구간(%/일); 7/28일은 JSON. 반복 개발·생존 거래소 선택·자료 빈티지 편향을 제거하지 못합니다.</p>'+table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')+'</details></section><section><h2>비용과 모든 지연·위험 조건</h2><p>현물10bp/선물5bp 수수료와 각1.5bp impact, 실제 funding, 최소수량·최소금액·5%p 조절밴드와 종료비용을 포함합니다. 변동성목표20%/명목상한1배. 비용2배·추가1/24h 실행지연·10%위험·추가24h 자료지연을 보존했습니다. 실제 호가·부분체결·역사별 규정·순간청산/운영 위험을 완전히 복원하지 못했습니다.</p><details id="matrix"><summary>60계좌 전체 보기</summary>'+table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts')+'</details></section>'
 html+='''<section id="proof"><h2>독립 검산과 소켓차단 재현</h2><p>14개 경계검사, 10,827개 별도 정규방정식 적합, 25,560일간 판단, 10,315폐형식 수량·41,479무거래, 15,396이벤트·51,120일말 자산을 검산했습니다. 실제 mark/funding·시간DD·노출·담보·연도별 수익과 기각 판정도 대조했습니다. 최대 계좌차2×10⁻¹¹USDT.</p><p>103파일 소켓차단 바이트 일치. 사전명세40c2613 → 자료동결63e6ce3 → 구현eef43ab 이후 계산했습니다. 검산 성공은 전략 성공이 아닙니다. 기존198계좌와 앞선764계좌는 재실행하지 않았습니다.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-venue-evidence.zip">60계좌·피처·예측·검산 ZIP ↓</a><a download href="downloads/btc-venue-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-venue-summary.csv">60조건 CSV ↓</a></div><p><a href="EXPERIMENT_BTC_VENUE_20261003.md">성과 전 명세·자료 동결</a> · <a href="BTC_WEB_RESEARCH_20261002.md">원문 감사·실패 기록</a> · <a href="https://doi.org/10.3390/risks7040111">가격전이 원문</a> · <a href="https://doi.org/10.1016/j.jfineco.2019.07.001">거래소 분절 원문</a></p><p>ZIP에는 파생 피처·계좌·원문 URL/SHA를 포함합니다. 동결한 거래소 전체 원시 응답/정규화가격·공식 Binance BTC 가격/펀딩·공통 의존성은 별도 재현 입력이며, 현재 API 재다운로드가 같은 빈티지임을 보장하지 않습니다.</p><p>정적 연구 기록입니다. 연구 목표는 미완료이며 실거래·상시모의 서비스는 없습니다.</p></section><footer>BUILD1003v1 · BTC-only · 실거래 없음</footer></main></body></html>'''
 (DOC/'btc-venue-research.html').write_text(html);p=DOC/'btc-web-research.html';old=p.read_text()
 if 'id="venue-followup"' not in old:p.write_text(old.replace('<h1>','<p id="venue-followup" class="boundary">추가60계좌: <a href="btc-venue-research.html">환산 거래소 공통 가격정보 검증 ↗</a></p><h1>',1))
 files=['btc-venue-research.html','btc-web-research.html','downloads/btc-venue-evidence.zip','downloads/btc-venue-evidence.json','downloads/btc-venue-summary.csv','EXPERIMENT_BTC_VENUE_20261003.md','BTC_WEB_RESEARCH_20261002.md'];out=ROOT/'runs/btc-venue-report-20261003';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files),'zip_bytes':(DOWN/'btc-venue-evidence.zip').stat().st_size}))
